/**
 * Free ports for app URLs declared with port 0. The runner picks them once,
 * after the config loads and before anything spawns, and hands the
 * assignments (`config.ports`, by target name) to every worker in its
 * bootstrap, so each process resolves the same app URLs from the same file.
 */
import net from 'node:net';
import { assignPorts } from '../config/resolve.js';
import { ConfigurationError, errorMessage } from '../internal/errors.js';
/**
 * The config with a free port assigned to every target whose URL asked for
 * one and has none yet; the same config when none did. Every port is held
 * until all are chosen, so two targets never receive the same one. A
 * loopback host this machine cannot bind is a bad app URL, reported before
 * anything starts.
 */
export async function allocateAppPorts(config) {
    return allocatePorts(config, config.targets);
}
/**
 * A port for one target alone, for a session that opens it and must not
 * fail on another target's URL. Returns the config and the target as it now reads.
 */
export async function allocateTargetPorts(config, target) {
    const allocated = await allocatePorts(config, [target]);
    return { config: allocated, target: allocated.targets.find((candidate) => candidate.name === target.name) };
}
async function allocatePorts(config, among) {
    const pending = among.filter((target) => target.app.portRequest !== undefined && !Object.hasOwn(config.ports, target.name));
    if (pending.length === 0)
        return config;
    const reserved = [];
    const ports = { ...config.ports };
    try {
        for (const { name, app } of pending) {
            const host = app.portRequest.host;
            let server;
            try {
                server = await reserve(host);
            }
            catch (cause) {
                throw new ConfigurationError('INVALID_APP_URL', `target "${name}" asks for a free port on ${host}, which this machine cannot bind: ${errorMessage(cause)}`, { cause });
            }
            reserved.push(server);
            ports[name] = portOf(server);
        }
    }
    finally {
        await Promise.all(reserved.map(release));
    }
    return assignPorts(config, ports);
}
/** Binds an ephemeral port on `host` and keeps it until released. */
function reserve(host) {
    return new Promise((resolve, reject) => {
        const server = net.createServer();
        server.once('error', reject);
        // A URL spells an IPv6 host in brackets; the socket API wants it bare.
        server.listen(0, host.startsWith('[') && host.endsWith(']') ? host.slice(1, -1) : host, () => resolve(server));
    });
}
function portOf(server) {
    const address = server.address();
    if (address === null || typeof address === 'string') {
        throw new Error('a listening TCP server has an address with a port');
    }
    return address.port;
}
function release(server) {
    return new Promise((resolve) => server.close(() => resolve()));
}
